Example

\(u''' = t + 2u + 3u''\), \(\; u(0) = 1\), \(u'(0) = 2\), \(u''(0) = 3\) Let \(y_0 = u\), \(y_1 = u'\), \(y_2 = u''\): \[
\begin{aligned}
y_0' &= y_1, & y_0(0) &= 1,\\
y_1' &= y_2, & y_1(0) &= 2,\\
y_2' &= t + 2y_0 + 3y_2, & y_2(0) &= 3.
\end{aligned}
\]

\[
\frac{d}{dt}
\begin{bmatrix}
y_0 \\
y_1 \\
y_2
\end{bmatrix}
=
\begin{bmatrix}
0 & 1 & 0 \\
0 & 0 & 1 \\
2 & 0 & 3
\end{bmatrix}
\begin{bmatrix}
y_0 \\
y_1 \\
y_2
\end{bmatrix}
+
\begin{bmatrix}
0 \\
0 \\
t
\end{bmatrix}
\]

MATLAB demo: forward Euler vs ode45
C = 0; % Parameter C in the model.
% The ODE rhs function as an "anonymous function".
f = @(t,u)  [u(2); -C*(u(1)^2 - 1).*u(2) - u(1)];

U0 = [2; -0.65];  % Initial condition
tspan = linspace(0,20,1e3); % Time span

% Set low tolerances to ensure an accurate solution
options = odeset('RelTol',1e-11,'AbsTol',1e-11);
[~,u_ode45] = ode45(f, tspan, U0);

% Forward Euler setup (timestep, vector of solution points etc)
dt = 0.15; n = round(tspan(end)/dt); u_Euler = NaN(2,n);

u_Euler(:,1) = U0; % Initial condition for Euler method
for i = 1:n-1
    t = (i-1) * dt; % Current time (NB: Unused currently!)
    u_Euler(:,i+1) = u_Euler(:,i) + dt * f(t, u_Euler(:,i));
end

MATLAB demo: equally spaced vs Chebyshev
f = @(x) 1 ./ (1 + 25*x.^2);      % Runge function
xx = linspace(-1, 1, 1000);
for n = [5 10 15 20]
    xe = linspace(-1, 1, n+1);                 % equally spaced nodes
    xc = cos((2*(0:n) + 1)*pi / (2*(n+1)));    % Chebyshev nodes
    pe = polyval(polyfit(xe, f(xe), n), xx);
    pc = polyval(polyfit(xc, f(xc), n), xx);
    fprintf('n = %2d: max error equispaced %.2e, Chebyshev %.2e\n', ...
        n, max(abs(f(xx) - pe)), max(abs(f(xx) - pc)));
end

